```js
function gecerli(s) {
  const es = { ")": "(", "]": "[", "}": "{" };
  const st = [];
  for (const c of s) {
    if ("([{".includes(c)) st.push(c);
    else if (st.pop() !== es[c]) return false;
  }
  return st.length === 0;
}
