function tersCevir(head) {
  let onceki = null, simdiki = head;
  while (simdiki) {
    const sonraki = simdiki.next;
    simdiki.next = onceki;
    onceki = simdiki;
    simdiki = sonraki;
  }
  return onceki;
}
