```js
class LRUCache {
  constructor(kapasite) {
    this.k = kapasite;
    this.m = new Map();
  }
  get(key) {
    if (!this.m.has(key)) return -1;
    const v = this.m.get(key);
    this.m.delete(key);
    this.m.set(key, v);
    return v;
  }
  put(key, v) {
    this.m.delete(key);
    this.m.set(key, v);
    if (this.m.size > this.k) this.m.delete(this.m.keys().next().value);
  }
}
